// Final-gate owner controls only. No account sign-in, profile save or live portal.
fn account_input(context:&Value,packet:&Value)->Value{json!({"expected_revision":0,"candidate_profile_id":packet["candidate_profile_id"],"profile_binding_id":context["profile_binding_id"],"account_sha256":"a".repeat(64),"evidence_sha256":"b".repeat(64),"owner_confirmed":true})}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_account_approval_requires_explicit_confirmation_primary_candidate_and_selected_browser(){
    let(mut c,context,packet)=browser_command_fixture().await;let input=account_input(&context,&packet);let profile_before:Value=sqlx::query_scalar("SELECT to_jsonb(p) FROM candidate_profiles p WHERE singleton_key='primary'").fetch_one(&mut c).await.unwrap();let before=browser_snapshot(&mut c).await;
    for kind in ["unconfirmed","candidate","browser"]{let mut invalid=input.clone();match kind{"unconfirmed"=>invalid["owner_confirmed"]=json!(false),"candidate"=>invalid["candidate_profile_id"]=json!(Uuid::new_v4()),_=>invalid["profile_binding_id"]=json!(Uuid::new_v4())};let error=execution_mutate(&mut c,automated_apply_agents::execution::Route::AccountApproval,invalid).await.unwrap_err();assert_eq!(error,Failure(if kind=="unconfirmed"{"owner_account_confirmation_required"}else{"account_binding_context_changed"}));assert_eq!(browser_snapshot(&mut c).await,before);}
    let saved=execution_mutate(&mut c,automated_apply_agents::execution::Route::AccountApproval,input.clone()).await.unwrap();assert_eq!(saved["revision"],1);assert_eq!(saved["approved"],true);assert_eq!(saved["source"],"owner_confirmed_profile_ui");assert_eq!(saved["candidate_profile_id"],packet["candidate_profile_id"]);let after:Value=sqlx::query_scalar("SELECT to_jsonb(p) FROM candidate_profiles p WHERE singleton_key='primary'").fetch_one(&mut c).await.unwrap();assert_eq!(after,profile_before);assert_eq!(execution_mutate(&mut c,automated_apply_agents::execution::Route::AccountApproval,input).await.unwrap_err(),Failure("account_binding_revision_conflict"));
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_account_approval_compare_and_swap_and_suppressed_ack_do_not_reset_identity(){
    let(mut c,context,packet)=browser_command_fixture().await;let input=account_input(&context,&packet);let before=browser_snapshot(&mut c).await;sqlx::raw_sql("CREATE FUNCTION fixture_account_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.key='naukri_account_binding' THEN RETURN NULL; END IF; RETURN NEW; END $$;CREATE TRIGGER fixture_account_drop BEFORE INSERT ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_account_drop()").execute(&mut c).await.unwrap();assert_eq!(execution_mutate(&mut c,automated_apply_agents::execution::Route::AccountApproval,input.clone()).await.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);sqlx::raw_sql("DROP TRIGGER fixture_account_drop ON owner_preferences;DROP FUNCTION fixture_account_drop()").execute(&mut c).await.unwrap();
    let mut other=connection().await;let(a,b)=tokio::join!(execution_mutate(&mut c,automated_apply_agents::execution::Route::AccountApproval,input.clone()),execution_mutate(&mut other,automated_apply_agents::execution::Route::AccountApproval,input));assert_eq!(usize::from(a.is_ok())+usize::from(b.is_ok()),1);assert!(matches!(a.err().or(b.err()).unwrap().0,"account_binding_revision_conflict"|"execution_database_error"));assert_eq!(browser_pref(&mut c,"naukri_account_binding").await["revision"],1);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_profile_sync_status_is_read_only_under_owner_lock_and_keeps_private_work_out(){
    let mut c=browser_fixture().await;browser_save(&mut c,"agent_conversation:primary",json!({})).await;let record=Uuid::new_v4();browser_save(&mut c,"apply_profile_sync:naukri",json!({"revision":7,"last_record":record,"last_error":null,"approved_summary":"PRIVATE_PROFILE_CANARY"})).await;browser_save(&mut c,&format!("nau_sync:{record}"),json!({"id":record,"outcome":"COMPARED","decisions":[]})).await;let before=browser_snapshot(&mut c).await;let mut owner=connection().await;let mut held=owner.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE").execute(&mut *held).await.unwrap();sqlx::query("SET lock_timeout='100ms'").execute(&mut c).await.unwrap();let data=automated_apply_agents::execution::dispatch(&mut c,automated_apply_agents::execution::Route::SyncStatus,"GET",None).await.unwrap();assert_eq!(data["configuration"]["revision"],0);assert_eq!(data["configuration"]["policy"]["enabled"],false);assert_eq!(data["current_profile_version"],4);assert_eq!(data["profile_confirmed"],true);assert_eq!(data["latest"]["id"],json!(record));assert_eq!(data["live_accepted"],false);assert_eq!(data["supported_updates"],json!(["skills","summary"]));assert!(!data.to_string().contains("PRIVATE_PROFILE_CANARY"));assert_eq!(browser_snapshot(&mut c).await,before);held.rollback().await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_profile_sync_policy_pins_confirmed_version_preserves_unknown_save_and_rollback_shape(){
    let mut c=browser_fixture().await;let route=automated_apply_agents::execution::Route::SyncPolicy;let before=browser_snapshot(&mut c).await;let input=json!({"expected_revision":0,"policy":{"enabled":true,"auto_profile_sync":true,"profile_version":3,"approved_fields":["summary","skills"]}});assert_eq!(execution_mutate(&mut c,route,input.clone()).await.unwrap_err(),Failure("current_confirmed_profile_version_required"));assert_eq!(browser_snapshot(&mut c).await,before);let mut input=input;input["policy"]["profile_version"]=json!(4);let saved=execution_mutate(&mut c,route,input).await.unwrap();assert_eq!(saved["revision"],1);assert!(saved["policy"].get("verify_saved_resume").is_none());
    let work=json!({"revision":8,"status":"executing","operation":"sync_profile","lease_token":Uuid::new_v4(),"lease_until":"2099-01-01T00:00:00Z","sync_attempt":{"id":Uuid::new_v4(),"outcome":"UNKNOWN"}});browser_save(&mut c,"apply_profile_sync:naukri",work.clone()).await;let before=browser_snapshot(&mut c).await;let update=json!({"expected_revision":1,"policy":{"enabled":false}});assert_eq!(execution_mutate(&mut c,route,update.clone()).await.unwrap_err(),Failure("profile_sync_in_progress_reconcile_before_change"));assert_eq!(browser_snapshot(&mut c).await,before);let mut inspecting=work.clone();inspecting["operation"]=json!("inspect_profile_sync");browser_save(&mut c,"apply_profile_sync:naukri",inspecting).await;let disabled=execution_mutate(&mut c,route,update).await.unwrap();assert_eq!(disabled["revision"],2);let retained=browser_pref(&mut c,"apply_profile_sync:naukri").await;assert_eq!(retained["sync_attempt"],work["sync_attempt"]);assert_eq!(retained["status"],"idle");assert!(retained["lease_token"].is_null());
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_account_and_sync_http_enforce_owner_methods_and_closed_contracts(){
    let(mut c,context,packet)=browser_command_fixture().await;let(url,stop,server)=http_fixture_values(browser_values()).await;let http=client();let account=format!("{url}/api/v1/execution/naukri/account-binding");let data=account_input(&context,&packet);assert_eq!(http.put(&account).json(&data).send().await.unwrap().status(),401);assert_eq!(http.put(&account).bearer_auth(HOST_TOKEN).header("x-agent-client",BROWSER_EXTENSION).json(&data).send().await.unwrap().status(),403);let approved=http.put(&account).bearer_auth(HOST_TOKEN).json(&data).send().await.unwrap();assert_eq!(approved.status(),200);assert_eq!(approved.json::<Value>().await.unwrap()["revision"],1);let bad=http.post(&account).bearer_auth(HOST_TOKEN).send().await.unwrap();assert_eq!(bad.status(),405);assert_eq!(bad.headers().get("allow").unwrap(),"GET, PUT");let sync=format!("{url}/api/v1/execution/naukri/profile-sync");assert_eq!(http.get(&sync).bearer_auth(HOST_TOKEN).header("x-agent-client",BROWSER_EXTENSION).send().await.unwrap().status(),403);assert_eq!(http.get(&sync).bearer_auth(HOST_TOKEN).send().await.unwrap().status(),200);assert_eq!(http.put(format!("{sync}/policy")).bearer_auth(HOST_TOKEN).json(&json!({"expected_revision":0,"policy":{"unrestricted":true}})).send().await.unwrap().status(),422);assert_eq!(browser_pref(&mut c,"naukri_account_binding").await["revision"],1);stop.cancel();server.await.unwrap();
}
